from agg import *
import warnings; warnings.simplefilter('ignore')
table('RESID: D21n energy, residual/total rms ratio, svd concentration',[('Y rms',lambda d:np.sqrt(d['S']['Y']['tot']/(1024*1023))),('res3/Y rms',lambda d:np.sqrt(d['S']['res_free3']['tot']/d['S']['Y']['tot'])),('res3N/Y',lambda d:np.sqrt(d['S']['res_free3N']['tot']/d['S']['Y']['tot'])),('noise/res3',lambda d:np.sqrt(d['S']['noise_tot']/d['S']['res_free3']['tot']))]+[(f'Y top{k}',Sq('Y','top',i)) for i,k in enumerate((1,2,4,16,64))]+[(f'res top{k}',Sq('res_free3','top',i)) for i,k in enumerate((1,2,4,16,64))]+[(f'resN top{k}',Sq('res_free3N','top',i)) for i,k in enumerate((1,4,16))]+[(f'wres top{k}',Sq('res_free3_w','top',i)) for i,k in enumerate((1,4,16))],LY,fmt='%.4f',width=12)
for t in (2.0,2.5,3.0):
    table(f'RESID row rms (normalised units x1e3) by row class tau={t}: residual(free3) | D21n | residual(free3+newborn)',[('res:'+c,lambda d,c=c,t=t:1e3*d['S']['rowrms'][f'{t}/{c}'][0]) for c in ('dead','kink','on')]+[('Y:'+c,lambda d,c=c,t=t:1e3*d['S']['rowrms'][f'{t}/{c}'][1]) for c in ('dead','kink','on')]+[('resN:'+c,lambda d,c=c,t=t:1e3*d['S']['rowrmsN'][f'{t}/{c}']) for c in ('dead','kink','on')],LY,fmt='%.3f',width=12)
table('RESID top singular vector correlations (abs): u1 (rows) / v1 (cols)',[('u1:'+k,lambda d,k=k:abs(d['S']['u1corr'][k])) for k in ('1','al','al2','absal','phi','Phi')]+[('v1:'+k,lambda d,k=k:abs(d['S']['v1corr'][k])) for k in ('1','al','al2','absal','phi','Phi')],LY,fmt='%.3f')
